[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$BackupManifest,[switch]$Execute,[string]$ApprovalPhrase,[switch]$Simulation,[string]$SimulationRoot='C:\VAMBAM\Projects\OTG\DEV\production_tooling_sandbox_107',[int]$SimulationPort=18502)
$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'production_update_common.ps1'); if($Simulation){Assert-Simulation $SimulationRoot $SimulationPort; if(-not $Execute){'MODE=DRY_RUN';'SIMULATION=YES';'MUTATION_EXECUTED=NO';exit 0}; Assert-Approval $Execute $ApprovalPhrase 'ROLLBACK_OTG_ANALYTICS_8502'; if(-not(Test-Path $BackupManifest)){throw 'BACKUP_MANIFEST_REQUIRED'}; $m=Get-Content $BackupManifest -Raw|ConvertFrom-Json; if($m.target_root -ne $SimulationRoot -or [int]$m.target_port -ne $SimulationPort -or $m.backup_complete -ne $true){throw 'BACKUP_MANIFEST_INVALID'}; Copy-Item (Join-Path (Split-Path $BackupManifest) '.env') (Join-Path $SimulationRoot 'production\.env') -Force; 'ROLLBACK_RESULT=PASS';'DB_SCHEMA_ROLLBACK=NOT_AUTOMATIC';'MUTATION_EXECUTED=YES';exit 0}; Assert-ProductionTarget; Assert-Approval $Execute $ApprovalPhrase 'ROLLBACK_OTG_ANALYTICS_8502'; if(-not(Test-Path $BackupManifest)){throw 'BACKUP_MANIFEST_REQUIRED'}; $m=Get-Content $BackupManifest -Raw|ConvertFrom-Json; if($m.target_root -ne $ExpectedRoot -or [int]$m.target_port -ne 8502 -or $m.backup_complete -ne $true){throw 'BACKUP_MANIFEST_INVALID'}; if(-not $m.old_git_head){throw 'OLD_HEAD_MISSING_FROM_MANIFEST'}
"MODE=$(if($Execute){'EXECUTE'}else{'DRY_RUN'})"; "ROLLBACK_TARGET_PORT=8502"; 'BACKUP_MANIFEST_VALID=YES'; "OLD_HEAD=$($m.old_git_head)"; 'DB_SCHEMA_ROLLBACK=NOT_AUTOMATIC'; 'ROLLBACK_ARTIFACT_POLICY=RESTORE_PRESENT_REMOVE_ONLY_MANIFEST_ABSENT'
Invoke-GuardedAction -Execute:$Execute -Name 'STOP_VERIFIED_8502_RESTORE_MANIFEST_STATE_START_OLD_APP' -Action { git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot reset --hard $m.old_git_head }; "MUTATION_EXECUTED=$(if($Execute){'YES'}else{'NO'})"
